DECLARE
  v_count integer := 0;
BEGIN
  -- Mark volumes as Purged where all jobs using them are expired
  UPDATE media SET volstatus = 'Purged'
  WHERE volstatus = 'Full'
    AND mediaid NOT IN (
      SELECT DISTINCT jm.mediaid FROM jobmedia jm
      JOIN job j ON jm.jobid = j.jobid
      WHERE j.jobstatus = 'T'
        AND j.realendtime > NOW() - INTERVAL '6 months'
    )
    AND (p_pool_name IS NULL OR poolid IN (SELECT poolid FROM pool WHERE name = p_pool_name));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;

DECLARE
  v_count integer := 0;
  v_client_id integer;
BEGIN
  IF p_client_name IS NOT NULL THEN
    SELECT clientid INTO v_client_id FROM client WHERE name = p_client_name;
  END IF;

  -- Delete jobmedia records for expired jobs
  DELETE FROM jobmedia WHERE jobid IN (
    SELECT jobid FROM job
    WHERE realendtime < NOW() - (p_days || ' days')::interval
      AND jobstatus IN ('T', 'E', 'f', 'A')
      AND (v_client_id IS NULL OR clientid = v_client_id)
  );

  -- Delete the jobs themselves
  DELETE FROM job
  WHERE realendtime < NOW() - (p_days || ' days')::interval
    AND jobstatus IN ('T', 'E', 'f', 'A')
    AND (v_client_id IS NULL OR clientid = v_client_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN v_count;
END;

DECLARE
  v_media_id integer;
  v_count integer := 0;
BEGIN
  SELECT mediaid INTO v_media_id FROM media WHERE volumename = p_volume_name;
  IF v_media_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Delete jobmedia records for this volume
  DELETE FROM jobmedia WHERE mediaid = v_media_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Reset volume status
  UPDATE media SET
    volstatus = 'Purged',
    voljobs = 0,
    volfiles = 0,
    volbytes = 0
  WHERE mediaid = v_media_id;

  RETURN v_count;
END;
